  const stackHeight=nodes=>nodes.reduce((sum,node)=>sum+node.h,0)+Math.max(0,nodes.length-1)*12;
  const H=Math.max(center.h,stackHeight(left),stackHeight(right))+24;
  center.x=startX+(left.length?columnWidth+gap:0)+(columnWidth-center.w)/2;center.y=(H-center.h)/2;
  function place(nodes,leftSide){
    let y=(H-stackHeight(nodes))/2;
    for(const node of nodes){node.x=leftSide?startX+columnWidth-node.w:startX+(columnCount-1)*(columnWidth+gap);node.y=y;y+=node.h+12;}
  }
  place(left,true);place(right,false);
  const nodes=[...left,center,...right],positions=new Map(nodes.map(node=>[node.id,node]));
  const ports=new Map();
  for(const [side,list] of [['left',leftEdges],['right',rightEdges]]){
    list.sort((a,b)=>positions.get(otherId(a)).y-positions.get(otherId(b)).y||a.edge_id.localeCompare(b.edge_id));
    list.forEach((edge,i)=>ports.set(edge.edge_id,{side,centerY:center.y+center.h/2+(i-(list.length-1)/2)*9}));
  }
  let paths='';
  for(const e of edges){
    const neighbor=positions.get(otherId(e)),port=ports.get(e.edge_id),leftSide=port.side==='left';
    const parallel=edges.filter(edge=>otherId(edge)===neighbor.id),index=parallel.indexOf(e);
    const neighborY=neighbor.y+neighbor.h/2+(index-(parallel.length-1)/2)*9;
    const centerPort=[leftSide?center.x-3:center.x+center.w+3,port.centerY];
    const neighborPort=[leftSide?neighbor.x+neighbor.w+3:neighbor.x-3,neighborY];
    const association=e.type==='annotation_association',org=e.basis==='analyst_organization';
    const rail=(centerPort[0]+neighborPort[0])/2+(association?1:-1)*(W>=640?4:1);
    const fromCenter=e.type==='subclass'?e.child===selected:e.source===selected;
    let points=[centerPort,[rail,centerPort[1]],[rail,neighborPort[1]],neighborPort];
    if(!fromCenter)points.reverse();
    const path=orthogonalPath(points),source=fromCenter?selected:neighbor.id,target=fromCenter?neighbor.id:selected;
    paths+=`<path class="svg-edge-hit" data-edge="${esc(e.edge_id)}" d="${path}"/><path id="edge-${esc(e.edge_id)}" class="svg-edge ${association?'annotation':org?'organizational':''}" data-edge="${esc(e.edge_id)}" data-source="${esc(source)}" data-target="${esc(target)}" d="${path}" marker-end="url(#arrow-${association?'association':org?'root':'subclass'})"><title>${esc(association?e.label:'is a type of')}</title></path>`;
  }
  $('graph').setAttribute('viewBox',`0 0 ${W} ${H}`);
  $('graph').innerHTML=`<defs>${[['subclass','var(--cyan)'],['association','var(--purple)'],['root','var(--muted)']].map(([id,c])=>`<marker id="arrow-${id}" markerUnits="userSpaceOnUse" markerWidth="8" markerHeight="8" viewBox="0 0 8 8" refX="8" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="${c}"/></marker>`).join('')}</defs>${paths}${nodes.map(nodeMarkup).join('')}`;
  $('graph-wrap').scrollTop=Math.max(0,(H-$('graph-wrap').clientHeight)/2);
  for(const g of $('graph').querySelectorAll('[data-role]')){
    g.addEventListener('click',()=>selectRole(g.dataset.role));
    g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRole(g.dataset.role);}});
  }
  for(const path of $('graph').querySelectorAll('[data-edge]'))path.addEventListener('click',()=>renderEdgeDetail(path.dataset.edge));
  $('edge-actions').replaceChildren();
  for(const edge of edges){
    const a=byId.get(edge.type==='subclass'?edge.child:edge.source),b=byId.get(edge.type==='subclass'?edge.parent:edge.target);
    const button=el('button',`${a.label} ${edge.type==='subclass'?'is a type of':edge.label} ${b.label}`,'edge-button');
    button.dataset.edgeButton=edge.edge_id;
    button.append(el('span',edge.basis==='analyst_organization'?'Organizing edge; no source claim':`${edge.source_ids.length} source passage${edge.source_ids.length===1?'':'s'} | ${edge.basis.replaceAll('_',' ')}`));
    button.addEventListener('click',()=>renderEdgeDetail(edge.edge_id));$('edge-actions').append(button);
  }
  if(!edges.length)$('edge-actions').append(el('p','No immediate relationships are recorded for the selected view.','muted small'));
